"import openpyxl

wb = openpyxl.load_workbook('ssb_279_23_init.xlsx')
ws = wb['Sheet1']

for row in range(3, 27):
    cell = ws.cell(row=row, column=2)
    value = cell.value

    if value is None or value == '':
        continue

    if isinstance(value, str):
        start = value.find('(')
        if start == -1:
            continue

        end = value.find(')', start + 1)
        if end == -1:
            continue

        content = value[start + 1:end]
        cell.value = content

wb.save('output.xlsx')"
